191	      cells: [...tr.querySelectorAll("td")].slice(2).map(td => td.textContent.trim()),
192	    }));
193	    return {
194	      selCount: text("#sel-count"),
195	      // renderSelection 重建的提示 span 没有保留静态 id，按可见文案识别更贴近用户所见
196	      selNoneHint: document.querySelector("#sel-list")?.textContent.includes("尚未勾选任何客户") ?? false,
