201	      checkAllChecked: document.getElementById("check-all").checked,
202	      checkAllIndeterminate: document.getElementById("check-all").indeterminate,
203	      tableDisplay: getComputedStyle(document.getElementById("clients-table")).display,
204	      emptyOn: document.getElementById("clients-empty").classList.contains("on"),
205	      loadErrorOn: document.getElementById("clients-load-error").classList.contains("on"),
206	      loadErrorText: text("#clients-load-error"),
207	      rows,
208	      fields: [...document.querySelectorAll("#batch-fields .bf")].map(card => ({
209	        key: card.dataset.field,
210	        op: card.querySelector('input[type=radio]:checked')?.value,
211	        value: card.querySelector(".bf-value").value,
212	        disabled: card.querySelector(".bf-value").disabled,
