307	function cleanedUp(snap) {
308	  return snap.selCount === "0" &&
309	    snap.selNoneHint && snap.selChips.length === 0 &&
310	    !snap.checkAllChecked && !snap.checkAllIndeterminate &&
311	    snap.rows.every(r => !r.checked && !r.selected) &&
312	    snap.fields.every(f => f.op === "keep" && f.value === "" && f.disabled) &&
313	    snap.submitText === "保存修改" && snap.submitDisabled;
314	}
