        check("E 正常路径：勾选清除、已选归零、四字段恢复、输入清空禁用、按钮恢复禁用",
          cleanedUp(snap), {sel: snap.selCount, fields: snap.fields});
        check("E 正常路径：保存请求仅 1 次",
          session.counts.batchPosts === beforePosts + 1, session.counts.batchPosts);
