          {sel: snap.selCount, rows: snap.rows, indeterminate: snap.checkAllIndeterminate});
        check("F 拒绝：来源仍为 set 且已填文本保留、输入可填写；行业仍为 clear；日期仍为 set 且保留非法值",
          snap.fields.find(f => f.key === "source").op === "set" &&
