#!/usr/bin/env node
/**
 * 临时验证：首页 CSV 导入结果显示的各种服务回复形态。
 * 启动真实 app.py，用 Puppeteer 请求拦截构造导入回复。
 */
import {spawn} from "node:child_process";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";
import {mkdtempSync, rmSync, writeFileSync} from "node:fs";
import {tmpdir} from "node:os";
import puppeteer from "puppeteer";

const HERE = dirname(fileURLToPath(import.meta.url));
const TMP = mkdtempSync(join(tmpdir(), "clientbook-import-"));
const FAILURES = [];
let checkCount = 0;
function check(label, cond, detail = "") {
  checkCount += 1;
  if (cond) console.log("PASS", label);
  else {
    FAILURES.push(label);
    console.log("FAIL", label, typeof detail === "string" ? detail : JSON.stringify(detail));
  }
}

function startApp(label) {
  const proc = spawn("python3", [join(HERE, "app.py"), "serve", "--host", "127.0.0.1",
    "--port", "0", "--data-dir", join(TMP, label)], {cwd: HERE, stdio: ["ignore", "pipe", "pipe"]});
  const port = new Promise((resolve, reject) => {
    let buf = "";
    const onData = d => {
      buf += d.toString();
      const m = buf.match(/http:\/\/127\.0\.0\.1:(\d+)/);
      if (m) { proc.stdout.off("data", onData); resolve(Number(m[1])); }
    };
    proc.stdout.on("data", onData);
    proc.on("exit", code => reject(new Error(`app.py exited ${code}: ${buf}`)));
  });
  return {proc, port};
}
async function waitReady(base) {
  for (let i = 0; i < 80; i++) {
    try { if ((await fetch(base + "/health")).status === 200) return; } catch {}
    await new Promise(r => setTimeout(r, 100));
  }
  throw new Error("not ready");
}
async function stopApp(ctx) {
  ctx.proc.kill();
  setTimeout(() => { try { ctx.proc.kill("SIGKILL"); } catch {} }, 2000);
  await new Promise(r => ctx.proc.on("exit", r));
}

async function openSession(browser, base) {
  const page = await browser.newPage();
  const modes = {importOverride: null, listMode: "ok", importPosts: 0};
  await page.setRequestInterception(true);
  page.on("request", request => {
    const url = request.url();
    if (request.method() === "POST" && url.endsWith("/api/clients/import")) {
      modes.importPosts += 1;
      if (modes.importOverride) {
        const {status = 200, body = "", contentType = "application/json; charset=utf-8"} = modes.importOverride;
        request.respond({status, contentType, body});
        return;
      }
    }
    if (request.method() === "GET" && url.endsWith("/api/clients") && modes.listMode === "close") {
      request.abort("failed");
      return;
    }
    request.continue();
  });
  await page.setCacheEnabled(false);
  await page.goto(base + "/", {waitUntil: "networkidle0"});
  const csvPath = join(TMP, "sample.csv");
  writeFileSync(csvPath, "name,source\n临时客户,展会\n");
  await page.evaluate(() => {});
  const input = await page.$("#file-input");
  await input.uploadFile(csvPath);
  await page.waitForFunction(() => document.getElementById("filename").textContent === "sample.csv");
  return {page, modes};
}

async function snap(page) {
  return page.evaluate(() => ({
    banners: [...document.querySelectorAll("#report .banner")].map(b => ({
      cls: b.className,
      text: b.innerText.replace(/[ \t\r\n]+/g, " ").trim(),
    })),
    text: document.getElementById("report").innerText.replace(/[ \t\r\n]+/g, " ").trim(),
    failureItems: [...document.querySelectorAll("#report .failures li")].map(li =>
      li.textContent.replace(/\s+/g, " ").trim()),
    btnDisabled: document.getElementById("submit-btn").disabled,
    fileKept: document.getElementById("file-input").files.length === 1 &&
      document.getElementById("filename").textContent === "sample.csv",
    selCount: document.getElementById("sel-count").textContent.trim(),
    rows: [...document.querySelectorAll("#clients-body tr")].length,
    emptyOn: document.getElementById("clients-empty").classList.contains("on"),
    loadErrorOn: document.getElementById("clients-load-error").classList.contains("on"),
  }));
}

async function submit(session) {
  const {page, modes} = session;
  const before = modes.importPosts;
  await page.click("#submit-btn");
  await page.waitForSelector("#report .banner", {timeout: 3000});
  await page.waitForFunction(() => document.getElementById("submit-btn").disabled === false, {timeout: 5000});
  await new Promise(r => setTimeout(r, 80));
  if (modes.importPosts !== before + 1) throw new Error("import 未发出/多发");
  return snap(page);
}

const J = (status, obj) => ({status, body: JSON.stringify(obj)});
const T = (status, text) => ({status, body: text, contentType: "text/plain; charset=utf-8"});

async function run() {
  const {proc, port: portP} = startApp("main");
  let base;
  try {
    base = `http://127.0.0.1:${await portP}`;
    await waitReady(base);
    // 准备两名真实客户，用于表格/勾选保留核对
    await fetch(base + "/api/clients/import", {method: "POST",
      body: "name,source\n真实甲,展会\n真实乙,广告\n"});

    const browser = await puppeteer.launch({
      executablePath: process.env.CHROME || "/usr/bin/google-chrome",
      headless: true, args: ["--no-sandbox", "--disable-dev-shm-usage"]});

    const assertBadNoSuccess = (label, s, extra) => {
      check(label + "：无绿色成功横幅", s.banners.every(b => !b.cls.includes("ok")), s.banners);
      check(label + "：不显示「新增 N 条」成功数量",
        !/新增\s*\d+\s*条/.test(s.text) && !/未导入\s*\d+\s*条/.test(s.text), s.text);
      check(label + "：不出现 undefined/NaN", !/undefined|NaN/.test(s.text), s.text);
      check(label + "：按钮结束等待、已选文件保留", !s.btnDisabled && s.fileKept,
        {disabled: s.btnDisabled, kept: s.fileKept});
      if (extra) extra(s);
    };

    try {
      // 1) HTTP 500 + JSON 错误说明（本次问题的原始场景）
      {
        const session = await openSession(browser, base);
        const {page, modes} = session;
        await page.evaluate(() => document.querySelector('#clients-body tr[data-id="1"] .row-check').click());
        modes.importOverride = J(500, {error: "模拟的内部错误：数据库写入失败"});
        const s = await submit(session);
        assertBadNoSuccess("500 JSON", s);
        check("500 JSON：展示可读错误说明", s.text.includes("模拟的内部错误"), s.text);
        check("500 JSON：说明没有取得可靠结果、提示先核对列表",
          s.text.includes("没有取得可靠的导入结果") && s.text.includes("请先核对客户列表"), s.text);
        check("500 JSON：不声称资料一定未变化/整份拒绝",
          !s.text.includes("整份文件已拒绝") && !s.text.includes("本次没有新增客户"), s.text);
        check("500 JSON：不清空已有客户表格与批量勾选",
          s.rows === 2 && s.selCount === "1", {rows: s.rows, sel: s.selCount});
        await page.close();
      }

      // 2) HTTP 500 + 纯文本错误说明
      {
        const session = await openSession(browser, base);
        session.modes.importOverride = T(500, "网关异常：上游超时");
        const s = await submit(session);
        assertBadNoSuccess("500 纯文本", s);
        check("500 纯文本：错误说明可读展示", s.text.includes("网关异常：上游超时"), s.text);
        await session.page.close();
      }

      // 3) 其他非成功状态（502）同样不能成功
      {
        const session = await openSession(browser, base);
        session.modes.importOverride = J(502, {error: "bad gateway", imported_count: 9, failed_count: 0});
        const s = await submit(session);
        assertBadNoSuccess("502 即使形似报告", s, x =>
          check("502：不采信回复中的数量 9", !x.text.includes("9"), x.text));
        await session.page.close();
      }

      // 4) 成功状态但无法解析 / 报告不完整
      const malformed = [
        ["无法解析", {raw: T(200, "<<<not json>>>")}],
        ["数量缺失", J(200, {failures: []})],
        ["新增为负数", J(200, {imported_count: -1, failed_count: 0, failures: []})],
        ["数量为浮点", J(200, {imported_count: 1.0, failed_count: 0.5, failures: []})],
        ["数量为字符串", J(200, {imported_count: "1", failed_count: "0", failures: []})],
        ["数量为布尔", J(200, {imported_count: true, failed_count: false, failures: []})],
        ["明细条数不符（多）", J(200, {imported_count: 0, failed_count: 0,
          failures: [{row: 1, reason: "x"}]})],
        ["明细条数不符（少）", J(200, {imported_count: 0, failed_count: 2,
          failures: [{row: 1, reason: "x"}]})],
        ["编号非正整数", J(200, {imported_count: 0, failed_count: 1,
          failures: [{row: 0, reason: "x"}]})],
        ["编号为字符串", J(200, {imported_count: 0, failed_count: 1,
          failures: [{row: "1", reason: "x"}]})],
        ["原因为空", J(200, {imported_count: 0, failed_count: 1,
          failures: [{row: 2, reason: "   "}]})],
        ["明细不是数组", J(200, {imported_count: 0, failed_count: 0, failures: null})],
        ["null 回复", J(200, null)],
      ];
      for (const [label, override] of malformed) {
        const session = await openSession(browser, base);
        session.modes.importOverride = override.raw;
        const s = await submit(session);
        assertBadNoSuccess("200 " + label, s);
        check(`200 ${label}：说明本次是否生效无法确认并提示核对列表`,
          s.text.includes("无法确认") && s.text.includes("核对客户列表") &&
            s.text.includes("不会自动重新提交"), s.text);
        check(`200 ${label}：不读取/刷新列表（报告不可信时表格保持 2 行原样）`,
          s.rows === 2, {rows: s.rows});
        await session.page.close();
      }

      // 5) 400 明确拒绝
      {
        const session = await openSession(browser, base);
        const {page, modes} = session;
        await page.evaluate(() => document.querySelector('#clients-body tr[data-id="1"] .row-check').click());
        modes.importOverride = J(400, {error: "缺少名称列：表头必须包含 name 列"});
        const s = await submit(session);
        check("400：红色横幅、无成功/警告横幅",
          s.banners.length === 1 && s.banners[0].cls.includes("bad") &&
          !s.banners.some(b => b.cls.includes("ok") || b.cls.includes("warn")), s.banners);
        check("400：明确整份拒绝、没有新增、资料保持原样",
          s.text.includes("整份文件已拒绝导入") && s.text.includes("本次没有新增客户"), s.text);
        check("400：给出具体原因", s.text.includes("缺少名称列"), s.text);
        check("400：勾选与表格保留、按钮恢复、文件保留",
          s.selCount === "1" && s.rows === 2 && !s.btnDisabled && s.fileKept, s);
        await page.close();
      }
      {
        const session = await openSession(browser, base);
        session.modes.importOverride = T(400, "编码错误：文件不是有效的 UTF-8 文本");
        const s = await submit(session);
        check("400 纯文本：仍按整份拒绝展示具体原因",
          s.banners.some(b => b.cls.includes("bad")) &&
          s.text.includes("整份文件已拒绝导入") && s.text.includes("UTF-8"), s.text);
        await session.page.close();
      }

      // 6) 合法成功报告：0/0、0 新增+全部未导入、部分新增
      {
        const session = await openSession(browser, base);
        session.modes.importOverride = J(200, {imported_count: 0, failed_count: 0,
          imported: [], failures: []});
        const s = await submit(session);
        check("0/0：绿色横幅显示两项数量均为零",
          s.banners.length === 1 && s.banners[0].cls.includes("ok") &&
          /新增\s*0\s*条/.test(s.text) && /未导入\s*0\s*条/.test(s.text), s.banners);
        check("0/0：无未导入明细块", s.failureItems.length === 0, s.failureItems);
        await session.page.close();
      }
      {
        const session = await openSession(browser, base);
        session.modes.importOverride = J(200, {imported_count: 0, failed_count: 2, failures: [
          {row: 1, reason: "名称与已有客户重复（已有客户编号 5），未更新"},
          {row: 3, reason: "重要日期无效（2025-13-40）：不是真实日历日期"}]});
        const s = await submit(session);
        check("全失败：绿色报告显示零新增与全部原因（记录级失败≠整份拒绝）",
          s.banners[0].cls.includes("ok") && /新增\s*0\s*条/.test(s.text) &&
          /未导入\s*2\s*条/.test(s.text) && !s.text.includes("整份文件已拒绝"), s.text);
        check("全失败：逐条显示编号与原因",
          s.failureItems.length === 2 &&
          s.failureItems[0].includes("第 1 条") && s.failureItems[0].includes("已有客户编号 5") &&
          s.failureItems[1].includes("第 3 条") && s.failureItems[1].includes("2025-13-40"),
          s.failureItems);
        await session.page.close();
      }
      {
        const session = await openSession(browser, base);
        session.modes.importOverride = J(200, {imported_count: 3, failed_count: 1,
          failures: [{row: 2, reason: "列数不符：表头有 5 列，该记录有 4 列"}]});
        const s = await submit(session);
        check("混合：保留部分新增报告并列出失败原因",
          /新增\s*3\s*条/.test(s.text) && /未导入\s*1\s*条/.test(s.text) &&
          s.failureItems.length === 1 && s.failureItems[0].includes("第 2 条"), s.text);
        await session.page.close();
      }

      // 7) 成功报告确认后，列表读取失败：保留报告+追加提示，不改说失败
      {
        const session = await openSession(browser, base);
        const {page, modes} = session;
        modes.importOverride = J(200, {imported_count: 1, failed_count: 1,
          failures: [{row: 2, reason: "缺少名称：name 列为空"}]});
        modes.listMode = "close";
        const s = await submit(session);
        modes.listMode = "ok";
        check("成功后列表失败：绿色数量报告保留",
          s.banners.some(b => b.cls.includes("ok") && /新增\s*1\s*条/.test(s.text) &&
            /未导入\s*1\s*条/.test(s.text)), s.banners);
        check("成功后列表失败：逐条原因保留",
          s.failureItems.length === 1 && s.failureItems[0].includes("第 2 条"), s.failureItems);
        check("成功后列表失败：追加列表暂未更新提示",
          s.banners.some(b => b.cls.includes("warn") && b.text.includes("列表暂未更新") &&
            b.text.includes("无需重新导入")), s.banners);
        check("成功后列表失败：旧表保留、不显示空列表", s.rows === 2 && !s.emptyOn,
          {rows: s.rows, empty: s.emptyOn});
        check("成功后列表失败：不把导入改说成失败", !s.text.includes("导入请求失败"), s.text);
        await page.close();
      }

      // 8) 真实端到端：坏文件 400、含错误行 200
      {
        const session = await openSession(browser, base);
        const {page} = session;
        const badPath = join(TMP, "bad.csv");
        writeFileSync(badPath, "name,source\n甲\"乙,展会\n");
        await page.$("#file-input").then(h => h.uploadFile(badPath));
        await page.click("#submit-btn");
        await page.waitForSelector("#report .banner.bad");
        await new Promise(r => setTimeout(r, 100));
        const s = await snap(page);
        check("真实坏 CSV：整份拒绝并说明结构原因",
          s.text.includes("整份文件已拒绝导入") && s.text.includes("双引号"), s.text);
        const goodPath = join(TMP, "good.csv");
        writeFileSync(goodPath, "name,important_date\n好客户,2024-02-29\n坏日期,2025-13-40\n");
        await page.$("#file-input").then(h => h.uploadFile(goodPath));
        await page.click("#submit-btn");
        await page.waitForFunction(() => /新增\s*1\s*条/.test(document.getElementById("report").innerText));
        await new Promise(r => setTimeout(r, 100));
        const s2 = await snap(page);
        check("真实混合 CSV：1 新增 1 未导入、原因逐条、列表已刷新",
          /新增\s*1\s*条/.test(s2.text) && /未导入\s*1\s*条/.test(s2.text) &&
          s2.failureItems.some(x => x.includes("第 2 条")) && s2.rows === 3, s2);
        await page.close();
      }

      await browser.close();
    } finally {}
  } finally {
    await stopApp({proc});
    rmSync(TMP, {recursive: true, force: true});
  }
  console.log(`\n${"=".repeat(50)}`);
  if (FAILURES.length) {
    console.log(`${FAILURES.length}/${checkCount} 失败：\n` + FAILURES.map(f => " - " + f).join("\n"));
    process.exitCode = 1;
  } else console.log(`全部通过（共 ${checkCount} 项导入结果断言）`);
}
run().catch(err => { console.error(err); process.exit(1); });

