#!/usr/bin/env node
/**
 * 临时验证：首页 CSV 导入结果显示的各种服务回复形态。
 * 启动真实 app.py，用 Puppeteer 请求拦截构造导入回复。
 */
import {spawn} from "node:child_process";
import {dirname, join} from "node:path";
import {fileURLToPath} from "node:url";
import {mkdtempSync, rmSync, writeFileSync} from "node:fs";
import {tmpdir} from "node:os";
import puppeteer from "puppeteer";

const HERE = dirname(fileURLToPath(import.meta.url));
const TMP = mkdtempSync(join(tmpdir(), "clientbook-import-"));
const FAILURES = [];
let checkCount = 0;
function check(label, cond, detail = "") {
  checkCount += 1;
  if (cond) console.log("PASS", label);
  else {
    FAILURES.push(label);
    console.log("FAIL", label, typeof detail === "string" ? detail : JSON.stringify(detail));
  }
}

function startApp(label) {
  const proc = spawn("python3", [join(HERE, "app.py"), "serve", "--host", "127.0.0.1",
    "--port", "0", "--data-dir", join(TMP, label)], {cwd: HERE, stdio: ["ignore", "pipe", "pipe"]});
  const port = new Promise((resolve, reject) => {
    let buf = "";
    const onData = d => {
      buf += d.toString();
      const m = buf.match(/http:\/\/127\.0\.0\.1:(\d+)/);
      if (m) { proc.stdout.off("data", onData); resolve(Number(m[1])); }
    };
    proc.stdout.on("data", onData);
    proc.on("exit", code => reject(new Error(`app.py exited ${code}: ${buf}`)));
  });
  return {proc, port};
}
async function waitReady(base) {
  for (let i = 0; i < 80; i++) {
    try { if ((await fetch(base + "/health")).status === 200) return; } catch {}
    await new Promise(r => setTimeout(r, 100));
  }
  throw new Error("not ready");
}
async function stopApp(ctx) {
  ctx.proc.kill();
  setTimeout(() => { try { ctx.proc.kill("SIGKILL"); } catch {} }, 2000);
  await new Promise(r => ctx.proc.on("exit", r));
}

async function openSession(browser, base) {
  const page = await browser.newPage();
  const modes = {importOverride: null, listMode: "ok", importPosts: 0};
  await page.setRequestInterception(true);
  page.on("request", request => {
    const url = request.url();
    if (request.method() === "POST" && url.endsWith("/api/clients/import")) {
      modes.importPosts += 1;
      if (modes.importOverride) {
        const {status = 200, body = "", contentType = "application/json; charset=utf-8"} = modes.importOverride;
        request.respond({status, contentType, body});
        return;
      }
    }
    if (request.method() === "GET" && url.endsWith("/api/clients") && modes.listMode === "close") {
      request.abort("failed");
      return;
    }
    request.continue();
  });
  await page.setCacheEnabled(false);
  await page.goto(base + "/", {waitUntil: "networkidle0"});
  const csvPath = join(TMP, "sample.csv");
  writeFileSync(csvPath, "name,source\n临时客户,展会\n");
  await page.evaluate(() => {});
  const input = await page.$("#file-input");
  await input.uploadFile(csvPath);
  await page.waitForFunction(() => document.getElementById("filename").textContent === "sample.csv");
  return {page, modes};
}

async function snap(page) {
  return page.evaluate(() => ({
    banners: [...document.querySelectorAll("#report .banner")].map(b => ({
      cls: b.className,
      text: b.innerText.replace(/[ \t\r\n]+/g, " ").trim(),
    })),
    text: document.getElementById("report").innerText.replace(/[ \t\r\n]+/g, " ").trim(),
    failureItems: [...document.querySelectorAll("#report .failures li")].map(li =>
      li.textContent.replace(/\s+/g, " ").trim()),
    btnDisabled: document.getElementById("submit-btn").disabled,
    fileKept: document.getElementById("file-input").files.length === 1 &&
      document.getElementById("filename").textContent === "sample.csv",
    selCount: document.getElementById("sel-count").textContent.trim(),
    rows: [...document.querySelectorAll("#clients-body tr")].length,
    emptyOn: document.getElementById("clients-empty").classList.contains("on"),
    loadErrorOn: document.getElementById("clients-load-error").classList.contains("on"),
  }));
}

async function submit(session) {
  const {page, modes} = session;
  const before = modes.importPosts;
  await page.click("#submit-btn");
  await page.waitForSelector("#report .banner", {timeout: 3000});
  await page.waitForFunction(() => document.getElementById("submit-btn").disabled === false, {timeout: 5000});
  await new Promise(r => setTimeout(r, 80));
  if (modes.importPosts !== before + 1) throw new Error("import 未发出/多发");
  return snap(page);
}

const J = (status, obj) => ({status, body: JSON.stringify(obj)});
const T = (status, text) => ({status, body: text, contentType: "text/plain; charset=utf-8"});

async function run() {
  const {proc, port: portP} = startApp("main");
  let base;
  try {
    base = `http://127.0.0.1:${await portP}`;
    await waitReady(base);
    // 准备两名真实客户，用于表格/勾选保留核对
    await fetch(base + "/api/clients/import", {method: "POST",
      body: "name,source\n真实甲,展会\n真实乙,广告\n"});

    const browser = await puppeteer.launch({
      executablePath: process.env.CHROME || "/usr/bin/google-chrome",
      headless: true, args: ["--no-sandbox", "--disable-dev-shm-usage"]});

    const assertBadNoSuccess = (label, s, extra) => {
      check(label + "：无绿色成功横幅", s.banners.every(b => !b.cls.includes("ok")), s.banners);
